<?php
/**
 * Master SVG del logotipo Akibara (8 piezas semánticas + armadura de tinta).
 *
 * En contexto `header` define en un único nodo DOM el gradiente `#akb-crimson`,
 * la armadura `#akb-outline`, las 7 letras (`letter-1-a` .. `letter-7-a3`) y el
 * subrayado caligráfico (`swoosh`). En contexto `footer` reutiliza cada pieza
 * mediante `<use href="#akb-...">` sin duplicar trazos vectoriales en el HTML.
 *
 * Args esperados (vía get_template_part( $slug, $name, $args ), WP 5.5+):
 *   - 'context' (string): 'header' (por defecto) | 'footer'.
 *
 * @package akibara-gp
 */

declare( strict_types = 1 );

defined( 'ABSPATH' ) || exit;

$akb_logo_args    = isset( $args ) && is_array( $args ) ? $args : array();
$akb_logo_context = isset( $akb_logo_args['context'] ) && 'footer' === $akb_logo_args['context'] ? 'footer' : 'header';

if ( 'footer' === $akb_logo_context ) :
	?>
<svg class="footer-brand__svg akb-logo-svg" xmlns="http://www.w3.org/2000/svg" width="201" height="80" viewBox="0 0 960 380" aria-hidden="true" focusable="false">
	<use class="akb-piece" data-piece="outline" href="#akb-outline"></use>
	<use class="akb-piece" data-piece="letter-1-a" href="#akb-letter-1-a"></use>
	<use class="akb-piece" data-piece="letter-2-k" href="#akb-letter-2-k"></use>
